export interface Subdivision {
  label: string;
  count: string;
}

export interface CountryMeta {
  alpha2: string;
  capital: string;
  subdivisions: Subdivision[];
  cities: string;
  summary: string;
}

function alphaToFlag(a2: string): string {
  return a2
    .toUpperCase()
    .split("")
    .map((c) => String.fromCodePoint(0x1f1e6 - 65 + c.charCodeAt(0)))
    .join("");
}

