const DEFAULT_META: CountryMeta = {
  alpha2: "UN",
  capital: "N/A",
  subdivisions: [],
  cities: "N/A",
  summary: "Explore this country to discover its unique geography, culture, and hidden gems.",
};

export function getCountryMeta(id: string): CountryMeta {
  return META[id] ?? DEFAULT_META;
}

export function getCountryFlag(alpha2: string): string {
  if (alpha2 === "UN" || alpha2 === "XNC") return alpha2 === "XNC" ? "\u{1F1F8}\u{1F1F0}" : "\u{1F310}";
  return alphaToFlag(alpha2);
}
